<?php

declare(strict_types=1);namespace Inilim\Tool\Method\Other;

function pagination(int $curPage,int $limitOnePage,int $countRecords):array{$obj=new class{function getAll(int $curPage,int $limitOnePage,int $countRecords):array{$limitOnePage=\abs($limitOnePage);$countRecords=\abs($countRecords);$countPages=$this -> getCountPages($limitOnePage,$countRecords);$curPage=$this -> getValidCurPage($curPage,$countPages);return['pageCount'=>$countPages,'recordCount'=>$countRecords,'recordPerPage'=>$limitOnePage,'curPage'=>$curPage,'offset'=>$this -> offset($curPage,$countPages,$limitOnePage),'next'=>$this -> next($curPage,$countPages),'prev'=>$this -> prev($curPage,$countPages),'isLast'=>$this -> isLast($curPage,$countPages),'isFirst'=>$this -> isFirst($curPage)];}function next(int $curPage,int $countPages):?int{$curPage=$this -> getValidCurPage($curPage,$countPages);$countPages=$this -> prepareCountPages($countPages);if($curPage===$countPages||$countPages===1){return null;}return $curPage+1;}function prev(int $curPage,int $countPages):?int{$curPage=$this -> getValidCurPage($curPage,$countPages);if($curPage===1){return null;}return $curPage-1;}function getCountPages(int $limitOnePage,int $countRecords):int{$limitOnePage=\abs($limitOnePage);if($limitOnePage===0){return 1;}$countRecords=\abs($countRecords);if($countRecords===0){return 1;}$c=\intval(\ceil($countRecords/$limitOnePage));return $c<=0?1:$c;}function offset(int $curPage,int $countPages,int $limitOnePage):int{$curPage=$this -> getValidCurPage($curPage,$countPages);$limitOnePage=\abs($limitOnePage);$offset=$curPage*$limitOnePage-$limitOnePage;return $offset<0?0:$offset;}function getValidCurPage(int $curPage,int $countPages):int{$curPage=$this -> prepareCurPage($curPage);if($curPage===1){return 1;}$countPages=$this -> prepareCountPages($countPages);return $curPage>$countPages?$countPages:$curPage;}function isLast(int $curPage,int $countPages):bool{$countPages=$this -> prepareCountPages($countPages);$curPage=$this -> prepareCurPage($curPage);return $curPage>=$countPages;}function isFirst(int $curPage):bool{return $this -> prepareCurPage($curPage)===1;}function prepareCurPage(int $curPage):int{return $curPage<=0?1:$curPage;}function prepareCountPages(int $countPages):int{$countPages=\abs($countPages);return $countPages===0?1:$countPages;}};return $obj -> getAll($curPage,$limitOnePage,$countRecords);}